-- 1411: Mirror WSQ courseware links + approved trainers from AI-LMS-TMS.
--
-- AI-LMS-TMS (lms-tms.tertiaryinfotech.com, repo alfredang/AI-LMS-TMS) is the
-- SOURCE OF TRUTH for WSQ (TGS-) courseware and the approved-trainer pool; the
-- storefront only mirrors it. Data pulled live 2026-09-16 over HTTPS from
-- GET /api/external/courses (307 TGS- courses). This migration replays that
-- pull so a rebuilt DB keeps the state.
--
--   course_courseware    -- the 6 Courseware-card links, UNIQUE(product_id)
--   mmd_product_trainer  -- approved trainer pool, UNIQUE(product_id,user_id)
--
-- Safety / partner notes:
--   * Products resolved by SKU, never a hardcoded product_id (ids drift between
--     local and prod).
--   * WSQ is SG-only. Every statement joins through a TGS- SKU, so on the MY/GH
--     partner servers (no TGS- products) this is a silent no-op.
--   * MySQL 5.7 target: NO REGEXP_REPLACE (8.0+ only -- it does not exist here
--     and would abort apply.php, 502ing every host). All name normalisation was
--     done at generation time; the SQL below only ever compares literals.
--   * Trainers link to EXISTING admin_user trainer accounts by normalised name.
--     The TMS trainers_email_list is EMPTY on all 307 courses, so email matching
--     is unavailable. No account is created here. 2978 of 3151 (name,course)
--     pairs resolve; the 17 unresolved names are listed at the end of this file.
--   * 4 names map to MORE THAN ONE active trainer account (duplicate accounts)
--     and are deliberately EXCLUDED rather than guessed -- linking the wrong
--     trainer to a course is worse than linking none.
--   * lab_url is NOT touched -- no TMS counterpart, must not be blanked.
--   * A blank TMS value never overwrites an existing storefront link
--     (COALESCE/NULLIF guard per column).
--   * All values are ASCII (verified at generation) -- no apply.php 1366 risk.
--   * Idempotent: upserts on the existing unique keys; a re-run is a no-op.

-- ---------------------------------------------------------------------------
-- 1. Courseware links
-- ---------------------------------------------------------------------------

CREATE TEMPORARY TABLE tmp_tms_courseware (
  sku VARCHAR(64) NOT NULL,
  learner_slides_url VARCHAR(1000) NOT NULL DEFAULT '',
  learner_guide_url  VARCHAR(1000) NOT NULL DEFAULT '',
  lesson_plan_url    VARCHAR(1000) NOT NULL DEFAULT '',
  trainer_slides_url VARCHAR(1000) NOT NULL DEFAULT '',
  courseware_link    VARCHAR(1000) NOT NULL DEFAULT '',
  brochure_link      VARCHAR(1000) NOT NULL DEFAULT '',
  PRIMARY KEY (sku)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


       lesson_plan_url, trainer_slides_url, courseware_link, brochure_link)
SELECT e.entity_id, t.learner_slides_url, t.learner_guide_url, t.lesson_plan_url,
       t.trainer_slides_url, t.courseware_link, t.brochure_link
  FROM tmp_tms_courseware t
  JOIN catalog_product_entity e ON e.sku = t.sku
ON DUPLICATE KEY UPDATE
  learner_slides_url = COALESCE(NULLIF(VALUES(learner_slides_url),''), course_courseware.learner_slides_url),
  learner_guide_url  = COALESCE(NULLIF(VALUES(learner_guide_url),''),  course_courseware.learner_guide_url),
  lesson_plan_url    = COALESCE(NULLIF(VALUES(lesson_plan_url),''),    course_courseware.lesson_plan_url),
  trainer_slides_url = COALESCE(NULLIF(VALUES(trainer_slides_url),''), course_courseware.trainer_slides_url),
  courseware_link    = COALESCE(NULLIF(VALUES(courseware_link),''),    course_courseware.courseware_link),
  brochure_link      = COALESCE(NULLIF(VALUES(brochure_link),''),      course_courseware.brochure_link);

DROP TEMPORARY TABLE tmp_tms_courseware;

-- ---------------------------------------------------------------------------
-- 2. Approved trainers
--
-- (sku, normalised trainer name, sort_order) straight from the TMS
-- trainers_list, pipe-split in TMS order. Names are matched to accounts by the
-- normalised-name table below, which is resolved against THIS server's
-- admin_user rows -- so a partner server with different accounts simply
-- matches fewer rows instead of linking the wrong person.
-- ---------------------------------------------------------------------------

CREATE TEMPORARY TABLE tmp_tms_course_trainer (
  sku VARCHAR(64) NOT NULL,
  norm_name VARCHAR(255) NOT NULL,
  sort_order INT UNSIGNED NOT NULL,
  PRIMARY KEY (sku, norm_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


-- Normalised name -> email for the accounts the generator resolved. Joined to
-- admin_user by EMAIL (stable identity) rather than a baked user_id, so this
-- migration is correct on any server whose user_ids differ.
CREATE TEMPORARY TABLE tmp_trainer_name_email (
  norm_name VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL,
  PRIMARY KEY (norm_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;


SELECT e.entity_id, u.user_id, t.sort_order, NOW()
  FROM tmp_tms_course_trainer t
  JOIN catalog_product_entity e ON e.sku = t.sku
  JOIN tmp_trainer_name_email x ON x.norm_name = t.norm_name
  JOIN admin_user u            ON u.email = x.email
  JOIN mmd_user_role_map m     ON m.user_id = u.user_id AND m.role_code = 'trainer';

DROP TEMPORARY TABLE tmp_tms_course_trainer;
DROP TEMPORARY TABLE tmp_trainer_name_email;

